#!/usr/bin/env node
// Generates the static case-study pages (work/<slug>/index.html) and the
// "Selected work" card grid on the homepage from content/work/projects.mjs.
//
//   node scripts/build-work-pages.mjs          write generated files
//   node scripts/build-work-pages.mjs --check  fail if generated files are stale
//
// Sketches are drawn in the browser (work/sketch/). The generator only reads each scene's
// design size so the canvas reserves the right space before the drawing arrives.
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { projects, site } from '../content/work/projects.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const CHECK = process.argv.includes('--check');
const GRID_START = '<!-- work-grid:start (generated by scripts/build-work-pages.mjs) -->';
const GRID_END = '<!-- work-grid:end -->';

// Scene registry: work/sketch/scenes/pNN.js each export { 'pNN-name': { size, narrow, draw } }.
const sceneDir = resolve(root, 'work/sketch/scenes');
const scenes = {};
for (const f of readdirSync(sceneDir).filter((f) => /^p\d+\.js$/.test(f))) {
  Object.assign(scenes, (await import(pathToFileURL(resolve(sceneDir, f)).href)).default);
}

const esc = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Minimal inline markup: **bold**, *italic*, [^n] footnote refs. Everything else is escaped.
const inline = (s, fnPrefix = 'fn') =>
  esc(s)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/\[\^(\d+)\]/g, (_, n) => `<sup class="fnref"><a href="#${fnPrefix}-${n}" id="${fnPrefix}ref-${n}-%%">${n}</a></sup>`);
const stripInline = (s) => String(s).replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*(.+?)\*/g, '$1').replace(/\[\^\d+\]/g, '');

// Bilingual span pair. `tag` wraps each language when block-level output is needed.
const bi = (t, tag = 'span', cls = '') => {
  if (t == null) return '';
  if (typeof t === 'string') return `<${tag}${cls ? ` class="${cls}"` : ''}>${inline(t)}</${tag}>`;
  const c = cls ? ` class="${cls}"` : '';
  return `<${tag}${c} data-en>${inline(t.en)}</${tag}><${tag}${c} data-ko lang="ko">${inline(t.ko)}</${tag}>`;
};

// Footnote back-reference ids must be unique per occurrence.
const uniqueRefs = (html) => {
  const seen = {};
  return html.replace(/id="(fn)ref-(\d+)-%%"/g, (_, p, n) => {
    seen[n] = (seen[n] || 0) + 1;
    return seen[n] === 1 ? `id="${p}ref-${n}"` : `id="${p}ref-${n}-${seen[n]}"`;
  });
};

const words = (s) => String(s).trim().split(/\s+/).filter(Boolean).length;
const collectText = (node, lang, acc = []) => {
  if (node == null) return acc;
  if (typeof node === 'string') return acc;
  if (Array.isArray(node)) { node.forEach((n) => collectText(n, lang, acc)); return acc; }
  if (typeof node === 'object') {
    if (typeof node.en === 'string' && typeof node.ko === 'string') { acc.push(node[lang]); return acc; }
    Object.values(node).forEach((v) => collectText(v, lang, acc));
  }
  return acc;
};
const readingTime = (p) => {
  const body = [p.glance, p.chapters, p.decisions, p.results, p.learned];
  const en = collectText(body, 'en').join(' ');
  const ko = collectText(body, 'ko').join('');
  return {
    en: `${Math.max(2, Math.round(words(en) / 230))} min read`,
    ko: `${Math.max(2, Math.round(ko.replace(/\s/g, '').length / 500))}분 분량`,
  };
};

// ---------- blocks ----------
const sketch = (b, extra = '') => {
  const sc = scenes[b.scene];
  if (!sc) throw new Error(`Unknown sketch scene: ${b.scene}`);
  if (!b.alt?.en || !b.alt?.ko) throw new Error(`Sketch ${b.scene} needs alt text in both languages`);
  const [w, h] = sc.size, [nw, nh] = sc.narrow;
  return `<figure class="cs-sketch${extra}" data-scene="${esc(b.scene)}" data-alt-en="${esc(b.alt.en)}" data-alt-ko="${esc(b.alt.ko)}" style="--ar: ${w} / ${h}; --ar-n: ${nw} / ${nh}">
  <canvas role="img" aria-label="${esc(b.alt.en)}"></canvas>
  ${b.caption ? `<figcaption>${bi(b.caption)}</figcaption>` : ''}
</figure>`;
};

const renderBlock = (b) => {
  switch (b.type) {
    case 'p':
      return bi(b, 'p');
    case 'list':
      return `<ul class="cs-list">${b.items.map((i) => `<li>${bi(i)}</li>`).join('')}</ul>`;
    case 'sketch':
      return `</div>\n${sketch(b)}\n<div class="cs-body-col">`;
    case 'metrics':
      return `<div class="cs-metric-table" role="table">${b.rows
        .map(
          (r) => `<div class="cs-metric-row" role="row">
  <div class="cs-metric-v" role="cell">${esc(r.value)}</div>
  <div class="cs-metric-l" role="cell">${bi(r.label)}${r.note ? `<span class="cs-metric-note">${bi(r.note)}</span>` : ''}</div>
</div>`
        )
        .join('')}</div>`;
    case 'quote':
      return `<blockquote class="cs-pull">${bi(b, 'p')}</blockquote>`;
    case 'note':
      return `<aside class="cs-note">${bi(b, 'p')}</aside>`;
    default:
      throw new Error(`Unknown block type: ${b.type}`);
  }
};

// A section is a text column that sketches break out of; empty columns are dropped.
const section = (id, heading, blocks, { num, after = '' } = {}) => {
  const inner = `<div class="cs-body-col">
  ${num ? `<span class="cs-chnum" aria-hidden="true">${esc(num)}</span>` : ''}<h2 id="${id}-h">${bi(heading)}</h2>
  ${blocks.map(renderBlock).join('\n  ')}
</div>${after}`.replace(/<div class="cs-body-col">\s*<\/div>/g, '');
  return `<section class="cs-section" id="${id}" aria-labelledby="${id}-h">
${inner}
</section>`;
};

const glance = (p) => {
  const g = p.glance;
  const items = [
    [{ en: 'Problem', ko: '문제' }, g.problem],
    [g.didLabel ?? { en: 'What we did', ko: '한 일' }, g.did],
    [g.resultLabel ?? { en: 'Result', ko: '결과' }, g.result],
  ];
  return `<section class="cs-glance" aria-labelledby="glance-h">
  <h2 id="glance-h" class="cs-glance-h">${bi({ en: 'At a glance', ko: '한눈에 보기' })}</h2>
  <ol>${items
    .map(([label, text], i) => `<li><div class="cs-glance-l"><span class="n">0${i + 1}</span>${bi(label)}</div>${bi(text, 'p')}</li>`)
    .join('')}</ol>
</section>`;
};

const kpiBand = (p) =>
  `<div class="cs-kpis">${p.kpis
    .map(
      (k) =>
        `<div class="cs-kpi"><div class="cs-kpi-v">${esc(k.value)}</div><div class="cs-kpi-l">${bi(k.label)}</div>${
          k.sub ? `<div class="cs-kpi-s">${bi(k.sub)}</div>` : ''
        }</div>`
    )
    .join('')}</div>`;

const metaRows = (p, rt) => {
  const rows = [
    [{ en: 'Company', ko: '회사' }, p.meta.company],
    [{ en: 'Role', ko: '역할' }, p.meta.role],
    [{ en: 'Scope', ko: '범위' }, p.meta.scope],
    [{ en: 'Stack', ko: '스택' }, p.stack.join(' · ')],
    [{ en: 'Reading time', ko: '읽는 시간' }, rt],
  ].filter(([, v]) => v);
  const link = p.meta.link
    ? `<div><dt>${bi({ en: 'Website', ko: '웹사이트' })}</dt><dd><a href="${esc(p.meta.link.url)}" target="_blank" rel="noopener">${esc(p.meta.link.label)} ↗</a></dd></div>`
    : '';
  return `<dl class="cs-meta">${rows.map(([k, v]) => `<div><dt>${bi(k)}</dt><dd>${bi(v)}</dd></div>`).join('')}${link}</dl>`;
};

const decisionsSection = (p) =>
  p.decisions?.length
    ? section('decisions', { en: 'Decisions', ko: '결정' }, [], {
        after: `\n<ul class="cs-decisions">${p.decisions
          .map(
            (d) => `<li class="cs-decision">
  <div class="cs-decision-label">${bi({ en: 'Decision', ko: '결정' })}</div>
  <h3>${bi(d.title)}</h3>
  ${bi(d.why, 'p')}
</li>`
          )
          .join('\n')}</ul>`,
      })
    : '';

const learnedSection = (p) => {
  const l = p.learned;
  const blocks = [];
  if (l.quote) blocks.push({ type: 'quote', ...l.quote });
  if (l.items?.length) blocks.push({ type: 'list', items: l.items });
  return section('learned', l.heading ?? { en: 'What I learned', ko: '배운 점' }, blocks);
};

const sourcesList = (p) => {
  if (!p.sources?.length) {
    return p.sourcesNote
      ? `<section class="cs-sources" aria-labelledby="sources-h">
  <h2 id="sources-h">${bi({ en: 'Notes', ko: '참고' })}</h2>
  ${bi(p.sourcesNote, 'p', 'cs-sources-lede')}
</section>`
      : '';
  }
  return `<section class="cs-sources" aria-labelledby="sources-h">
  <h2 id="sources-h">${bi({ en: 'Sources', ko: '출처' })}</h2>
  ${bi(
    p.sourcesNote ?? {
      en: 'Numbered notes point to public announcements and press coverage. Project metrics are internal measurements from my time at SOOP.',
      ko: '번호 각주는 공개 공지와 보도 자료입니다. 프로젝트 지표는 SOOP 재직 당시의 내부 측정치입니다.',
    },
    'p',
    'cs-sources-lede'
  )}
  <ol>${p.sources
    .map(
      (s, i) =>
        `<li id="fn-${i + 1}">${esc(s.publisher)}, “${esc(s.title)}” <span class="cs-src-date">(${esc(s.date)})</span>. <a href="${esc(
          s.url
        )}" target="_blank" rel="noopener">${bi({ en: 'Link', ko: '링크' })}</a> <a class="cs-back" href="#fnref-${i + 1}" aria-label="Back to text">↩</a></li>`
    )
    .join('')}</ol>
</section>`;
};

const topbar = () => `<header class="topbar">
  <div class="topbar-inner">
    <a href="/" class="brand"><span class="brand-mark">IK</span><span>InJoo Kim</span></a>
    <div class="top-actions">
      <a class="cs-back-link" href="/#work">← ${bi({ en: 'Selected work', ko: '프로젝트' })}</a>
      <button class="icon-btn" id="lang-btn" type="button" aria-label="Switch language">KO</button>
      <button class="icon-btn" id="theme-btn" type="button" aria-label="Toggle dark mode">◐</button>
    </div>
  </div>
</header>`;

// Applies saved language/theme before first paint, sharing the homepage's storage keys.
const bootScript = `<script>
(function(){var d=document.documentElement;try{var l=localStorage.getItem('portfolio-lang');if(l==='ko'||l==='en'){d.setAttribute('data-lang',l);d.lang=l;}var t=localStorage.getItem('portfolio-theme');if(t==='dark'||t==='light')d.setAttribute('data-theme',t);}catch(e){}})();
</script>`;

const pad = (n) => String(n).padStart(2, '0');

const pageHtml = (p, i) => {
  const rt = readingTime(p);
  const prev = projects[(i - 1 + projects.length) % projects.length];
  const next = projects[(i + 1) % projects.length];
  const url = `${site.origin}/work/${p.slug}/`;
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: p.title.en,
    description: p.dek.en,
    author: { '@type': 'Person', name: 'InJoo Kim', url: site.origin },
    url,
    inLanguage: ['en', 'ko'],
  };
  const chapters = p.chapters.map((c, n) => section(c.id, c.heading, c.blocks, { num: pad(n + 1) })).join('\n');
  const results = section('results', p.results.heading ?? { en: 'Results', ko: '결과' }, p.results.blocks);

  return uniqueRefs(`<!DOCTYPE html>
<html lang="en" data-lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>${esc(p.title.en)} — InJoo Kim</title>
<meta name="description" content="${esc(p.dek.en)}" />
<link rel="canonical" href="${url}" />
<meta property="og:type" content="article" />
<meta property="og:title" content="${esc(p.title.en)} — ${esc(p.id)} case study" />
<meta property="og:description" content="${esc(p.dek.en)}" />
<meta property="og:url" content="${url}" />
<meta name="twitter:card" content="summary" />
<meta name="theme-color" content="#efe7d6" />
<link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png" />
<link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png" />
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Gaegu:wght@400;700&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;0,6..72,600;1,6..72,400&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css" />
${bootScript}
<script type="application/ld+json">${JSON.stringify(jsonLd)}</script>
<script type="module" src="/work/case-study.js"></script>
</head>
<body class="cs-body">
<a class="skip-link" href="#main">${bi({ en: 'Skip to content', ko: '본문으로 건너뛰기' })}</a>
${topbar()}
<main id="main">
<article class="cs">
  <header class="cs-head">
    <p class="cs-eyebrow"><span>${bi({ en: 'Case study', ko: '케이스 스터디' })}</span><span class="cs-dot">·</span><span>${esc(
      p.id
    )}</span><span class="cs-dot">·</span><span>${esc(p.company)}</span></p>
    <h1>${bi(p.title)}</h1>
    ${bi(p.dek, 'p', 'cs-dek')}
    ${metaRows(p, rt)}
  </header>
  ${sketch(p.hero, ' cs-hero')}
  ${glance(p)}
  ${kpiBand(p)}
${chapters}
${decisionsSection(p)}
${results}
${learnedSection(p)}
  <div class="cs-body-col">
${sourcesList(p)}
  </div>
</article>
<nav class="cs-pager" aria-label="${esc('More case studies')}">
  <a href="/work/${prev.slug}/" class="cs-pager-card" rel="prev">
    <span class="cs-pager-dir">← ${esc(prev.id)}</span>
    <span class="cs-pager-title">${bi(prev.title)}</span>
  </a>
  <a href="/#work" class="cs-pager-card cs-pager-all">
    <span class="cs-pager-dir">${bi({ en: 'All work', ko: '전체 프로젝트' })}</span>
    <span class="cs-pager-title">${bi({ en: 'Back to selected work', ko: '프로젝트 목록으로' })}</span>
  </a>
  <a href="/work/${next.slug}/" class="cs-pager-card" rel="next">
    <span class="cs-pager-dir">${esc(next.id)} →</span>
    <span class="cs-pager-title">${bi(next.title)}</span>
  </a>
</nav>
</main>
<footer class="cs-footer">
  <span>© 2026 InJoo Kim</span>
  <span><a href="/">injookim.com</a> · <a href="/#contact">${bi({ en: 'Get in touch', ko: '연락하기' })}</a></span>
</footer>
</body>
</html>
`);
};

// ---------- validation ----------
const used = new Set();
for (const p of projects) {
  const n = p.sources?.length ?? 0;
  const refs = collectText([p.glance, p.chapters, p.decisions, p.results, p.learned], 'en')
    .concat(collectText([p.glance, p.chapters, p.decisions, p.results, p.learned], 'ko'))
    .join(' ')
    .match(/\[\^(\d+)\]/g) ?? [];
  for (const r of refs) if (+r.slice(2, -1) > n) throw new Error(`${p.id}: footnote ${r} has no source`);
  const sketches = [p.hero, ...p.chapters.flatMap((c) => c.blocks), ...p.results.blocks].filter((b) => b && (b.type === 'sketch' || b === p.hero));
  sketches.forEach((b) => used.add(b.scene));
  for (const b of sketches) if (stripInline(b.alt?.en ?? '').length < 20) throw new Error(`${p.id}: alt text for ${b.scene} is too short`);
}
const unused = Object.keys(scenes).filter((s) => !used.has(s));
if (unused.length) console.warn(`note: scenes defined but not used: ${unused.join(', ')}`);

// Homepage card markup (kept visually identical to the previous hand-written cards).
const cardHtml = (p) => `      <a class="work-card work-card-link" href="/work/${p.slug}/">
        <div class="work-head">
          <span class="work-idx">${esc(p.id)}</span>
          <span class="work-co">${esc(p.company)}</span>
        </div>
        <h3 class="work-title"><span data-en>${esc(p.title.en)}</span><span data-ko>${esc(p.title.ko)}</span></h3>
        <p class="work-desc"><span data-en>${esc(p.card.en)}</span><span data-ko>${esc(p.card.ko)}</span></p>
        <div class="work-kpis">
${p.kpis
  .filter((k) => k.card !== false)
  .map((k) => `          <div class="work-kpi"><div class="n">${esc(k.value)}</div><div class="l">${esc(k.cardLabel ?? k.label.en)}</div></div>`)
  .join('\n')}
        </div>
        <div class="work-stack">${p.stack.map((s) => `<span class="tag">${esc(s)}</span>`).join('')}</div>
        <span class="work-more"><span data-en>Read case study</span><span data-ko>케이스 스터디 보기</span> →</span>
      </a>`;

// ---------- write / check ----------
const outputs = [];
projects.forEach((p, i) => outputs.push([resolve(root, 'work', p.slug, 'index.html'), pageHtml(p, i)]));

const indexPath = resolve(root, 'index.html');
const index = readFileSync(indexPath, 'utf8');
const a = index.indexOf(GRID_START);
const b = index.indexOf(GRID_END);
if (a === -1 || b === -1 || b < a) throw new Error('index.html is missing the work-grid markers');
const grid = `${GRID_START}\n${projects.map(cardHtml).join('\n\n')}\n      ${GRID_END}`;
outputs.push([indexPath, index.slice(0, a) + grid + index.slice(b + GRID_END.length)]);

let stale = [];
for (const [path, html] of outputs) {
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current === html) continue;
  if (CHECK) { stale.push(path); continue; }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, html);
  console.log(`wrote ${path.replace(root + '/', '')}`);
}
if (CHECK && stale.length) {
  console.error(`Generated work pages are stale; run \`npm run work:build\`:\n${stale.map((s) => `  ${s.replace(root + '/', '')}`).join('\n')}`);
  process.exit(1);
}
if (CHECK) console.log('work pages up to date');
